import { createHash } from 'node:crypto';
import { mkdir, readFile, rm, writeFile } from 'node:fs/promises';
import { join, resolve, sep } from 'node:path';
import {
  type AppEnvironment,
  assertProviderAllowed,
  type ProviderDescriptor,
  ProviderNotAllowedError,
} from './provider.js';

/**
 * Private storage for lender evidence documents. Bytes never get a public URL: the API reads them
 * after an authorisation check and streams them back. Keys are opaque and generated by the API;
 * names, PAN, Aadhaar or lender identifiers never appear in a key.
 */
export interface DocumentStore {
  readonly descriptor: ProviderDescriptor;
  put(key: string, bytes: Uint8Array, meta: { mimeType: string; sha256: string }): Promise<void>;
  get(key: string): Promise<{ bytes: Uint8Array; mimeType: string } | undefined>;
  delete(key: string): Promise<void>;
}

const KEY_PATTERN = /^[A-Za-z0-9/_-]{8,200}$/;

/** Rejects keys that could escape the storage root or are not generated by this system. */
export function assertValidDocumentKey(key: string): void {
  if (!KEY_PATTERN.test(key) || key.includes('..') || key.startsWith('/') || key.includes('//')) {
    throw new Error('invalid document key');
  }
}

export function sha256Hex(bytes: Uint8Array): string {
  return createHash('sha256').update(bytes).digest('hex');
}

/**
 * Local-disk store for development and tests ONLY. It is a mock: files are unencrypted. It refuses
 * to be created for staging or production, on top of the provider guard.
 */
export function createLocalDocumentStore(
  rootDirectory: string,
  environment: AppEnvironment,
): DocumentStore {
  const descriptor: ProviderDescriptor = {
    key: 'local_disk_documents',
    capability: 'object_storage',
    mode: 'mock',
  };
  assertProviderAllowed(descriptor, environment);
  if (environment !== 'local' && environment !== 'test') {
    throw new ProviderNotAllowedError(
      'the local document store holds unencrypted files and is only for local development and tests',
    );
  }
  const root = resolve(rootDirectory);
  const pathFor = (key: string): string => {
    assertValidDocumentKey(key);
    const full = resolve(join(root, key));
    if (!full.startsWith(root + sep)) throw new Error('invalid document key');
    return full;
  };
  const mimeKey = (key: string) => `${pathFor(key)}.mime`;
  return {
    descriptor,
    async put(key, bytes, meta) {
      if (sha256Hex(bytes) !== meta.sha256) throw new Error('document checksum mismatch');
      const path = pathFor(key);
      await mkdir(resolve(path, '..'), { recursive: true });
      await writeFile(path, bytes, { mode: 0o600, flag: 'wx' });
      await writeFile(mimeKey(key), meta.mimeType, { mode: 0o600 });
    },
    async get(key) {
      try {
        const [bytes, mime] = await Promise.all([
          readFile(pathFor(key)),
          readFile(mimeKey(key), 'utf8'),
        ]);
        return { bytes: new Uint8Array(bytes), mimeType: mime };
      } catch (error) {
        if ((error as NodeJS.ErrnoException).code === 'ENOENT') return undefined;
        throw error;
      }
    },
    async delete(key) {
      await rm(pathFor(key), { force: true });
      await rm(mimeKey(key), { force: true });
    },
  };
}

/** The subset of an S3 client this adapter needs, so tests (and any SDK version) can supply it. */
export interface ObjectStorageClient {
  putObject(input: {
    bucket: string;
    key: string;
    body: Uint8Array;
    contentType: string;
    /** KMS key used for server-side encryption (SSE-KMS). */
    kmsKeyId: string;
    sha256Hex: string;
  }): Promise<void>;
  getObject(input: {
    bucket: string;
    key: string;
  }): Promise<{ body: Uint8Array; contentType: string } | undefined>;
  deleteObject(input: { bucket: string; key: string }): Promise<void>;
}

/**
 * S3-compatible store for AWS ap-south-1 (Mumbai). Always uses SSE-KMS with the given key. The
 * bucket must block public access; that is infrastructure and is checked at deployment, not here.
 */
export function createObjectStorageDocumentStore(
  client: ObjectStorageClient,
  options: { bucket: string; kmsKeyId: string },
): DocumentStore {
  if (!options.bucket || !options.kmsKeyId) {
    throw new Error('bucket and kmsKeyId are required: documents are always encrypted at rest');
  }
  return {
    descriptor: { key: 'aws_s3_kms_documents', capability: 'object_storage', mode: 'production' },
    async put(key, bytes, meta) {
      assertValidDocumentKey(key);
      if (sha256Hex(bytes) !== meta.sha256) throw new Error('document checksum mismatch');
      await client.putObject({
        bucket: options.bucket,
        key,
        body: bytes,
        contentType: meta.mimeType,
        kmsKeyId: options.kmsKeyId,
        sha256Hex: meta.sha256,
      });
    },
    async get(key) {
      assertValidDocumentKey(key);
      const object = await client.getObject({ bucket: options.bucket, key });
      return object ? { bytes: object.body, mimeType: object.contentType } : undefined;
    },
    async delete(key) {
      assertValidDocumentKey(key);
      await client.deleteObject({ bucket: options.bucket, key });
    },
  };
}
